const std::size_t kDecompCount = sizeof(kDecomp) / sizeof(kDecomp[0]);
const std::size_t kCccCount = sizeof(kCcc) / sizeof(kCcc[0]);
const std::size_t kComposeCount = sizeof(kCompose) / sizeof(kCompose[0]);

const std::uint32_t kSBase = 0xAC00u;
const std::uint32_t kLBase = 0x1100u;
const std::uint32_t kVBase = 0x1161u;
const std::uint32_t kTBase = 0x11A7u;
const std::uint32_t kLCount = 19u;
const std::uint32_t kVCount = 21u;
const std::uint32_t kTCount = 28u;
const std::uint32_t kNCount = kVCount * kTCount;
const std::uint32_t kSCount = kLCount * kNCount;

int ccc_of(std::uint32_t cp) {
  std::size_t lo = 0;
  std::size_t hi = kCccCount;
  while (lo < hi) {
    const std::size_t mid = (lo + hi) / 2;
    if (kCcc[mid].cp == cp) return static_cast<int>(kCcc[mid].ccc);
    if (kCcc[mid].cp < cp) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return 0;
}

const DecompRecord* find_decomp(std::uint32_t cp) {
  std::size_t lo = 0;
  std::size_t hi = kDecompCount;
  while (lo < hi) {
    const std::size_t mid = (lo + hi) / 2;
    if (kDecomp[mid].cp == cp) return &kDecomp[mid];
    if (kDecomp[mid].cp < cp) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return nullptr;
}

std::uint32_t compose_pair(std::uint32_t a, std::uint32_t b) {
  std::size_t lo = 0;
  std::size_t hi = kComposeCount;
  while (lo < hi) {
    const std::size_t mid = (lo + hi) / 2;
    const ComposeRecord& rec = kCompose[mid];
    if (rec.first == a && rec.second == b) return rec.composite;
    if (rec.first < a || (rec.first == a && rec.second < b)) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return 0;
}

void append_decomposed(std::uint32_t cp, std::vector<std::uint32_t>& out, int depth) {
  if (depth > 32) {
    out.push_back(cp);
    return;
  }
  if (cp >= kSBase && cp < kSBase + kSCount) {
    const std::uint32_t index = cp - kSBase;
    out.push_back(kLBase + index / kNCount);
    out.push_back(kVBase + (index % kNCount) / kTCount);
    const std::uint32_t trail = index % kTCount;
    if (trail != 0) out.push_back(kTBase + trail);
    return;
  }
  const DecompRecord* rec = find_decomp(cp);
  if (rec == nullptr) {
    out.push_back(cp);
    return;
  }
  append_decomposed(rec->first, out, depth + 1);
  if (rec->second != 0) append_decomposed(rec->second, out, depth + 1);
}

