std::string unicode_normalize_nfc(const std::string& utf8) {
  std::vector<std::uint32_t> points;
  points.reserve(utf8.size());
  const std::size_t len = utf8.size();
  std::size_t i = 0;
  while (i < len) {
    const unsigned char lead = static_cast<unsigned char>(utf8[i]);
    std::uint32_t cp = lead;
    std::size_t extra = 0;
    if (lead < 0x80u) {
      cp = lead;
    } else if ((lead & 0xE0u) == 0xC0u) {
      cp = lead & 0x1Fu;
      extra = 1;
    } else if ((lead & 0xF0u) == 0xE0u) {
      cp = lead & 0x0Fu;
      extra = 2;
    } else if ((lead & 0xF8u) == 0xF0u) {
      cp = lead & 0x07u;
      extra = 3;
    } else {
      cp = 0xFFFDu;
      extra = 0;
    }
    if (i + extra >= len && extra != 0) {
      points.push_back(0xFFFDu);
      break;
    }
    bool ok = true;
    for (std::size_t k = 1; k <= extra; ++k) {
      const unsigned char cont = static_cast<unsigned char>(utf8[i + k]);
      if ((cont & 0xC0u) != 0x80u) {
        ok = false;
        break;
      }
      cp = (cp << 6) | (cont & 0x3Fu);
    }
    points.push_back(ok ? cp : 0xFFFDu);
    i += extra + 1;
  }

  std::vector<std::uint32_t> decomposed;
  decomposed.reserve(points.size() * 2);
  for (std::uint32_t cp : points) append_decomposed(cp, decomposed, 0);

  for (std::size_t a = 0; a < decomposed.size(); ++a) {
    const int cls = ccc_of(decomposed[a]);
    if (cls == 0) continue;
    std::size_t b = a;
    while (b > 0 && ccc_of(decomposed[b - 1]) > cls) {
      const std::uint32_t tmp = decomposed[b - 1];
      decomposed[b - 1] = decomposed[b];
      decomposed[b] = tmp;
      --b;
    }
  }

  std::vector<std::uint32_t> composed;
  composed.reserve(decomposed.size());
  for (std::uint32_t cp : decomposed) {
    if (!composed.empty()) {
      const std::uint32_t prev = composed.back();
      std::uint32_t merged = 0;
      if (prev >= kLBase && prev < kLBase + kLCount && cp >= kVBase && cp < kVBase + kVCount) {
        merged = kSBase + ((prev - kLBase) * kVCount + (cp - kVBase)) * kTCount;
      } else if (prev >= kSBase && prev < kSBase + kSCount && ((prev - kSBase) % kTCount) == 0 &&
                 cp > kTBase && cp < kTBase + kTCount) {
        merged = prev + (cp - kTBase);
      } else if (ccc_of(prev) == 0 || ccc_of(cp) == 0) {
        merged = compose_pair(prev, cp);
      }
      if (merged != 0) {
        composed.back() = merged;
        continue;
      }
    }
    composed.push_back(cp);
  }

  std::string out;
  out.reserve(utf8.size());
  for (std::uint32_t cp : composed) {
    if (cp < 0x80u) {
      out.push_back(static_cast<char>(cp));
    } else if (cp < 0x800u) {
      out.push_back(static_cast<char>(0xC0u | (cp >> 6)));
      out.push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    } else if (cp < 0x10000u) {
      out.push_back(static_cast<char>(0xE0u | (cp >> 12)));
      out.push_back(static_cast<char>(0x80u | ((cp >> 6) & 0x3Fu)));
      out.push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    } else {
      out.push_back(static_cast<char>(0xF0u | (cp >> 18)));
      out.push_back(static_cast<char>(0x80u | ((cp >> 12) & 0x3Fu)));
      out.push_back(static_cast<char>(0x80u | ((cp >> 6) & 0x3Fu)));
      out.push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    }
  }
  return out;
}

